use quote::quote;
use std::collections::HashMap;

use crate::eqcheck::compute_eq_derivable;
use crate::model::*;

/// Prepended to every generated file (including hand-assembled ones like
/// `mod.rs`, see `main.rs`). Comments aren't tokens, so this can't be baked
/// into the `quote!` output -- it has to be applied to the final rendered
/// string, after `prettyplease::unparse`.
pub const GENERATED_FILE_BANNER: &str = "\
// @generated by ocpp-codegen from schemas/. Do not edit by hand -- run
// `scripts/generate.sh` to regenerate; manual changes will be overwritten.

";

fn with_generated_banner(code: String) -> String {
    format!("{GENERATED_FILE_BANNER}{code}")
}

/// A spec-bounded `Vec` above this capacity stops being stack-friendly (a
/// `heapless::Vec<T, N>` is `N * size_of::<T>()` bytes inline, so a large
/// `N` can blow up a struct -- and, transitively, any future holding it
/// across an `.await` -- to tens of megabytes). Above this size, the
/// `alloc` build switches it to a heap-allocated `alloc::Vec<T>` instead,
/// same as a genuinely unbounded field; the `heapless` capacity is still
/// enforced in the `no_std`/no-`alloc` build, where there's no heap to fall
/// back to.
const MAX_STACK_VEC_CAPACITY: usize = 64;

pub fn generate(schema: ParsedSchema) -> String {
    let eq_by_name = compute_eq_derivable(&schema.types);
    let const_params = crate::generics::compute_const_params(&schema.types);
    let message_params = crate::generics::params_for_fields(&schema.message.fields, &const_params);

    let mut tokens = generate_struct(&schema.message, &message_params, &eq_by_name, &const_params);

    for ty in &schema.types {
        tokens.extend(match ty {
            GeneratedType::Struct(s) => {
                let own = const_params.get(&s.name).cloned().unwrap_or_default();
                generate_struct(s, &own, &eq_by_name, &const_params)
            }
            GeneratedType::Enum(e) => generate_enum(e),
        });
    }

    with_generated_banner(prettyplease::unparse(&syn::parse2(tokens).unwrap()))
}

/// Renders a single message struct on its own, importing shared types from
/// a sibling `common` module instead of embedding them. `eq_by_name` and
/// `const_params` must come from [`compute_eq_derivable`] /
/// [`crate::generics::compute_const_params`] run over the *full* shared
/// [`crate::pool::TypePool`] (every schema file in the batch), since a
/// message can reference a common type whose `Eq`-ness or generic params
/// depend on types this individual message never touches directly. Pair
/// with [`generate_common`] so a definition referenced by several messages
/// (e.g. `CustomDataType`) is generated once in `common.rs` rather than
/// once per message file.
pub fn generate_message(
    message: &RustStruct,
    eq_by_name: &HashMap<String, bool>,
    const_params: &HashMap<String, Vec<ConstParam>>,
) -> String {
    let own_params = crate::generics::params_for_fields(&message.fields, const_params);
    let struct_tokens = generate_struct(message, &own_params, eq_by_name, const_params);

    // Only pull in `common` when a field actually needs a bare name from
    // it (a `Local` type, possibly through a `Vec`) -- otherwise the import
    // is unused, which every version of `ocpp-types` currently trips for
    // most single-field messages.
    let needs_common = message.fields.iter().any(|f| references_local(&f.ty));
    let common_import = needs_common.then(|| quote! { use super::common::*; });

    let tokens = quote! {
        #common_import

        #struct_tokens
    };

    with_generated_banner(prettyplease::unparse(&syn::parse2(tokens).unwrap()))
}

fn references_local(ty: &RustType) -> bool {
    match ty {
        RustType::Local(_) => true,
        RustType::Vec(inner, _) => references_local(inner),
        RustType::UnboundedVec(inner, _) => references_local(inner),
        _ => false,
    }
}

/// Renders every type in a shared pool into the contents of a `common.rs`
/// module, for use alongside [`generate_message`].
pub fn generate_common(types: &[GeneratedType]) -> String {
    let eq_by_name = compute_eq_derivable(types);
    let const_params = crate::generics::compute_const_params(types);
    let mut tokens = proc_macro2::TokenStream::new();

    for ty in types {
        tokens.extend(match ty {
            GeneratedType::Struct(s) => {
                let own = const_params.get(&s.name).cloned().unwrap_or_default();
                generate_struct(s, &own, &eq_by_name, &const_params)
            }
            GeneratedType::Enum(e) => generate_enum(e),
        });
    }

    with_generated_banner(prettyplease::unparse(&syn::parse2(tokens).unwrap()))
}

/// Renders a schema `description` as a sequence of `#[doc = "..."]`
/// attributes (one per source line), which `prettyplease` prints back as
/// `///` doc comments. Empty when there's no description to attach.
fn doc_attrs(description: &Option<String>) -> proc_macro2::TokenStream {
    let Some(description) = description else {
        return quote! {};
    };

    let lines = description.lines().map(|line| {
        // A leading space keeps the rendered `///` from butting straight up
        // against the text (`///Foo` vs `/// Foo`).
        let line = format!(" {}", line.trim_end());
        quote! { #[doc = #line] }
    });

    quote! { #(#lines)* }
}

/// Renders a struct. When `own_params` is empty (the common case -- no
/// unbounded field anywhere in this struct's transitive closure), this is
/// a single ordinary definition, unchanged from before generics existed.
/// Otherwise it renders *two* definitions, `#[cfg]`-gated: one where every
/// unbounded field is `alloc::string::String`/`alloc::vec::Vec<T>` (no
/// generics at all), and one where they're `heapless` collections sized by
/// caller-choosable const params (with defaults, so existing call sites
/// don't need to specify them).
fn generate_struct(
    model: &RustStruct,
    own_params: &[ConstParam],
    eq_by_name: &HashMap<String, bool>,
    const_params: &HashMap<String, Vec<ConstParam>>,
) -> proc_macro2::TokenStream {
    // An oversized bounded `Vec` (see `MAX_STACK_VEC_CAPACITY`) needs the
    // alloc/no_alloc split too, even with no caller-chosen params anywhere
    // in the struct -- otherwise the alloc build never gets a chance to
    // switch it away from a giant inline `heapless::Vec`. Unlike an
    // `UnboundedVec`'s param, this doesn't propagate to callers of `Local`
    // fields: the capacity is fixed by the spec, not chosen by the caller,
    // so only the struct that directly owns the field needs to know.
    let has_oversized_vec = model
        .fields
        .iter()
        .any(|f| matches!(&f.ty, RustType::Vec(_, capacity) if *capacity > MAX_STACK_VEC_CAPACITY));

    if own_params.is_empty() && !has_oversized_vec {
        return generate_struct_body(model, eq_by_name, const_params, false, &[], &quote! {});
    }

    // `#[cfg(...)] #tokens` only ever gates the single item immediately
    // following it -- if `#tokens` expands to two sibling items (the
    // struct and its `impl Action`), the attribute silently binds to just
    // the first and the second compiles unconditionally in both modes,
    // producing two overlapping `impl Action` for the same (default- or
    // explicitly-applied) type. So the gate is threaded *into*
    // `generate_struct_body` and applied to each item there individually,
    // rather than wrapped around the outside of a multi-item stream here.
    let alloc_cfg = quote! { #[cfg(feature = "alloc")] };
    let no_alloc_cfg = quote! { #[cfg(not(feature = "alloc"))] };

    let alloc_body = generate_struct_body(model, eq_by_name, const_params, true, &[], &alloc_cfg);
    let no_alloc_body =
        generate_struct_body(model, eq_by_name, const_params, false, own_params, &no_alloc_cfg);

    quote! {
        #alloc_body
        #no_alloc_body
    }
}

fn generate_struct_body(
    model: &RustStruct,
    eq_by_name: &HashMap<String, bool>,
    const_params: &HashMap<String, Vec<ConstParam>>,
    alloc_mode: bool,
    own_params: &[ConstParam],
    cfg_gate: &proc_macro2::TokenStream,
) -> proc_macro2::TokenStream {
    let name = ident(&model.name);
    let struct_doc = doc_attrs(&model.description);
    let struct_generics = generic_params_with_defaults(own_params);

    let fields = model.fields.iter().map(|field| {
        let rust_name = crate::naming::rust_name(&field.name);
        let fname = field_ident(&rust_name);
        let ftype = rust_type(&field.ty, alloc_mode, const_params);
        let ftype = if field.optional {
            quote! { Option<#ftype> }
        } else {
            ftype
        };
        let field_doc = doc_attrs(&field.description);

        // Without this, an absent optional field still serializes as an
        // explicit `"field":null` instead of being omitted -- which is
        // both wasted bytes and not what OCPP implementations expect.
        let skip_if_none = field.optional.then(|| {
            quote! {
                #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
            }
        });

        // serde's default field name is the Rust identifier, which is
        // snake_case; OCPP's wire format is camelCase, so anything that
        // diverges needs an explicit rename to round-trip correctly.
        if rust_name == field.name {
            quote! {
                #field_doc
                #skip_if_none
                pub #fname: #ftype
            }
        } else {
            let original = &field.name;
            quote! {
                #field_doc
                #[cfg_attr(feature = "serde", serde(rename = #original))]
                #skip_if_none
                pub #fname: #ftype
            }
        }
    });

    let eq_derive = if crate::eqcheck::fields_are_eq(&model.fields, eq_by_name) {
        quote! { , Eq }
    } else {
        quote! {}
    };

    let action_impl = model.action.as_ref().map(|action| {
        // `impl<const N: usize = 8> ...` isn't legal -- defaults are only
        // allowed on the type definition itself, so the impl header
        // repeats the same params without them.
        let impl_generics = generic_params_without_defaults(own_params);
        let type_generics = generic_args(own_params);
        quote! {
            #cfg_gate
            impl #impl_generics crate::Action for #name #type_generics {
                const ACTION: &'static str = #action;
            }
        }
    });

    quote! {
        #cfg_gate
        #struct_doc
        #[derive(Debug, Clone, PartialEq #eq_derive)]
        #[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
        pub struct #name #struct_generics {

            #(
                #fields,
            )*
        }

        #action_impl
    }
}

fn generate_enum(model: &RustEnum) -> proc_macro2::TokenStream {
    let name = ident(&model.name);
    let enum_doc = doc_attrs(&model.description);

    let variants = model.variants.iter().map(|variant| {
        let vident = ident(&variant.ident);

        if variant.ident == variant.raw {
            quote! { #vident }
        } else {
            let raw = &variant.raw;
            quote! {
                #[cfg_attr(feature = "serde", serde(rename = #raw))]
                #vident
            }
        }
    });

    quote! {
        #enum_doc
        #[derive(Debug, Clone, PartialEq, Eq)]
        #[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
        pub enum #name {

            #(
                #variants,
            )*
        }
    }
}

fn ident(name: &str) -> proc_macro2::Ident {
    proc_macro2::Ident::new(name, proc_macro2::Span::call_site())
}

fn field_ident(name: &str) -> proc_macro2::Ident {
    if crate::naming::is_rust_keyword(name) {
        proc_macro2::Ident::new_raw(name, proc_macro2::Span::call_site())
    } else {
        proc_macro2::Ident::new(name, proc_macro2::Span::call_site())
    }
}

/// `<const P1: usize = D1, const P2: usize = D2>`, or empty when `params`
/// is empty. Defaults are only legal here, on the type definition itself.
fn generic_params_with_defaults(params: &[ConstParam]) -> proc_macro2::TokenStream {
    if params.is_empty() {
        return quote! {};
    }

    let decls = params.iter().map(|p| {
        let name = ident(&p.name);
        let default = p.default;
        quote! { const #name: usize = #default }
    });

    quote! { < #(#decls),* > }
}

/// Same as [`generic_params_with_defaults`], but without the `= default`
/// part -- for `impl<...>` headers, which don't allow defaults.
fn generic_params_without_defaults(params: &[ConstParam]) -> proc_macro2::TokenStream {
    if params.is_empty() {
        return quote! {};
    }

    let decls = params.iter().map(|p| {
        let name = ident(&p.name);
        quote! { const #name: usize }
    });

    quote! { < #(#decls),* > }
}

/// `<P1, P2>`, or empty when `params` is empty -- for applying a set of
/// params as arguments (e.g. `impl<...> Action for Foo<P1, P2>`, or a field
/// referencing a generic `Local` type by its own required params).
fn generic_args(params: &[ConstParam]) -> proc_macro2::TokenStream {
    if params.is_empty() {
        return quote! {};
    }

    let names = params.iter().map(|p| ident(&p.name));

    quote! { < #(#names),* > }
}

fn rust_type(
    ty: &RustType,
    alloc_mode: bool,
    const_params: &HashMap<String, Vec<ConstParam>>,
) -> proc_macro2::TokenStream {
    match ty {
        RustType::Bool => quote! { bool },

        RustType::Integer => quote! { i64 },

        RustType::Number => quote! { f64 },

        RustType::BoundedString(size) => quote! {
            heapless::String<#size>
        },

        RustType::Primitive(name) => {
            let ident = ident(name);
            quote! { super::#ident }
        }

        RustType::Local(name) => {
            let ident = ident(name);
            // In `alloc` mode every generic-affected type has already
            // collapsed to a concrete (non-generic) definition, so it's
            // always referenced bare there. Otherwise it needs whichever
            // subset of *this* struct's own params it requires -- which
            // are in scope under the same names, since they were threaded
            // up from exactly this reference in the first place.
            if alloc_mode {
                quote! { #ident }
            } else {
                let params = const_params.get(name).map(Vec::as_slice).unwrap_or(&[]);
                let args = generic_args(params);
                quote! { #ident #args }
            }
        }

        RustType::Vec(inner, capacity) => {
            let inner_ty = rust_type(inner, alloc_mode, const_params);
            if alloc_mode && *capacity > MAX_STACK_VEC_CAPACITY {
                quote! { alloc::vec::Vec<#inner_ty> }
            } else {
                quote! { heapless::Vec<#inner_ty, #capacity> }
            }
        }

        RustType::UnboundedString(param) => {
            if alloc_mode {
                quote! { alloc::string::String }
            } else {
                let p = ident(&param.name);
                quote! { heapless::String<#p> }
            }
        }

        RustType::UnboundedVec(inner, param) => {
            let inner_ty = rust_type(inner, alloc_mode, const_params);
            if alloc_mode {
                quote! { alloc::vec::Vec<#inner_ty> }
            } else {
                let p = ident(&param.name);
                quote! { heapless::Vec<#inner_ty, #p> }
            }
        }

        RustType::Unknown => quote! { () },
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample_schema() -> ParsedSchema {
        ParsedSchema {
            message: RustStruct {
                name: "AuthorizeRequest".to_string(),
                action: Some("Authorize".to_string()),
                description: None,
                fields: vec![RustField {
                    name: "idTag".to_string(),
                    ty: RustType::Primitive("IdTag".to_string()),
                    optional: false,
                    description: None,
                }],
            },
            types: Vec::new(),
        }
    }

    #[test]
    fn derives_debug_clone_partial_eq_eq() {
        let code = generate(sample_schema());

        assert!(code.contains("Debug"));
        assert!(code.contains("Clone"));
        assert!(code.contains("PartialEq"));
        assert!(code.contains("Eq"));
    }

    #[test]
    fn struct_description_becomes_a_doc_comment() {
        let mut schema = sample_schema();
        schema.message.description = Some("Sent by the Charge Point.".to_string());

        let code = generate(schema);

        assert!(code.contains("/// Sent by the Charge Point."));
    }

    #[test]
    fn field_description_becomes_a_doc_comment_above_the_field() {
        let mut schema = sample_schema();
        schema.message.fields[0].description = Some("The unique identifier.".to_string());

        let code = generate(schema);

        assert!(code.contains("/// The unique identifier."));
    }

    #[test]
    fn multi_line_description_becomes_one_doc_line_per_source_line() {
        let mut schema = sample_schema();
        schema.message.description = Some("Line one.\nLine two.".to_string());

        let code = generate(schema);

        assert!(code.contains("/// Line one."));
        assert!(code.contains("/// Line two."));
    }

    #[test]
    fn struct_with_no_description_gets_no_doc_comment() {
        let code = generate(sample_schema());

        assert!(!code.contains("///"));
    }

    #[test]
    fn enum_description_becomes_a_doc_comment() {
        let mut schema = sample_schema();
        schema.types.push(GeneratedType::Enum(RustEnum {
            name: "BootReasonEnum".to_string(),
            description: Some("Reason for sending this message.".to_string()),
            variants: vec![RustVariant {
                ident: "PowerUp".to_string(),
                raw: "PowerUp".to_string(),
            }],
        }));

        let code = generate(schema);

        assert!(code.contains("/// Reason for sending this message."));
    }

    #[test]
    fn generate_prepends_a_generated_file_banner() {
        let code = generate(sample_schema());

        assert!(code.starts_with("// @generated"));
        assert!(code.contains("Do not edit"));
    }

    #[test]
    fn generate_message_prepends_a_generated_file_banner() {
        let message = RustStruct {
            name: "AuthorizeRequest".to_string(),
            action: Some("Authorize".to_string()),
            description: None,
            fields: Vec::new(),
        };

        let code = generate_message(&message, &HashMap::new(), &HashMap::new());

        assert!(code.starts_with("// @generated"));
    }

    #[test]
    fn generate_common_prepends_a_generated_file_banner() {
        let code = generate_common(&[]);

        assert!(code.starts_with("// @generated"));
    }

    #[test]
    fn serde_derive_is_gated_behind_feature() {
        let code = generate(sample_schema());

        assert!(code.contains("cfg_attr(feature = \"serde\""));
        assert!(code.contains("Serialize"));
        assert!(code.contains("Deserialize"));
    }

    #[test]
    fn wrapper_types_are_referenced_via_the_version_module() {
        // Generated files (message and common alike) live directly inside
        // their version module, which re-exports its `primitives`, so
        // `super::Name` resolves regardless of which version generated it.
        let code = generate(sample_schema());

        assert!(code.contains("super :: IdTag") || code.contains("super::IdTag"));
    }

    #[test]
    fn message_struct_implements_action_trait() {
        let code = generate(sample_schema());

        assert!(
            code.contains("impl crate::Action for AuthorizeRequest")
                || code.contains("impl crate :: Action for AuthorizeRequest")
        );
        assert!(
            code.contains("const ACTION: & 'static str = \"Authorize\"")
                || code.contains("const ACTION: &'static str = \"Authorize\"")
        );
    }

    #[test]
    fn optional_field_is_wrapped_in_option() {
        let mut schema = sample_schema();
        schema.message.fields[0].optional = true;

        let code = generate(schema);

        assert!(code.contains("Option<super::IdTag>") || code.contains("Option < super :: IdTag >"));
    }

    #[test]
    fn field_named_type_is_escaped_as_raw_identifier() {
        let mut schema = sample_schema();
        schema.message.fields[0].name = "type".to_string();

        let code = generate(schema);

        assert!(code.contains("r#type"));
    }

    #[test]
    fn camel_case_field_gets_serde_rename_to_original_json_key() {
        let code = generate(sample_schema());

        assert!(code.contains("pub id_tag: super::IdTag"));
        assert!(code.contains("rename = \"idTag\""));
    }

    #[test]
    fn field_that_already_matches_its_rust_name_has_no_rename() {
        let mut schema = sample_schema();
        schema.message.fields[0].name = "reason".to_string();
        schema.message.fields[0].ty = RustType::Bool;

        let code = generate(schema);

        assert!(!code.contains("rename"));
    }

    #[test]
    fn optional_field_gets_skip_serializing_if_none() {
        let mut schema = sample_schema();
        schema.message.fields[0].optional = true;

        let code = generate(schema);

        assert!(code.contains("skip_serializing_if = \"Option::is_none\""));
    }

    #[test]
    fn required_field_has_no_skip_serializing_if() {
        let code = generate(sample_schema());

        assert!(!code.contains("skip_serializing_if"));
    }

    #[test]
    fn generate_message_emits_only_the_message_struct_with_a_common_glob_import() {
        let message = RustStruct {
            name: "AuthorizeRequest".to_string(),
            action: Some("Authorize".to_string()),
            description: None,
            fields: vec![RustField {
                name: "customData".to_string(),
                ty: RustType::Local("CustomData".to_string()),
                optional: true,
                description: None,
            }],
        };

        let code = generate_message(&message, &HashMap::new(), &HashMap::new());

        assert!(code.contains("use super::common::*"));
        assert!(code.contains("pub struct AuthorizeRequest"));
        assert!(code.contains("Option<CustomData>"));
        assert!(!code.contains("pub struct CustomData {"));
    }

    #[test]
    fn generate_message_omits_the_common_import_when_nothing_needs_it() {
        let message = RustStruct {
            name: "HeartbeatRequest".to_string(),
            action: Some("Heartbeat".to_string()),
            description: None,
            fields: Vec::new(),
        };

        let code = generate_message(&message, &HashMap::new(), &HashMap::new());

        assert!(!code.contains("use super::common"));
    }

    #[test]
    fn generate_message_includes_the_common_import_when_a_vec_of_local_types_is_used() {
        let message = RustStruct {
            name: "MeterValuesRequest".to_string(),
            action: Some("MeterValues".to_string()),
            description: None,
            fields: vec![RustField {
                name: "meterValue".to_string(),
                ty: RustType::Vec(Box::new(RustType::Local("MeterValue".to_string())), 4),
                optional: false,
                description: None,
            }],
        };

        let code = generate_message(&message, &HashMap::new(), &HashMap::new());

        assert!(code.contains("use super::common::*"));
    }

    #[test]
    fn generate_common_emits_every_pooled_type() {
        let types = vec![
            GeneratedType::Struct(RustStruct {
                name: "CustomData".to_string(),
                action: None,
                description: None,
                fields: vec![RustField {
                    name: "vendorId".to_string(),
                    ty: RustType::BoundedString(255),
                    optional: false,
                    description: None,
                }],
            }),
            GeneratedType::Enum(RustEnum {
                name: "LocationEnum".to_string(),
                description: None,
                variants: vec![RustVariant {
                    ident: "Outlet".to_string(),
                    raw: "Outlet".to_string(),
                }],
            }),
        ];

        let code = generate_common(&types);

        assert!(code.contains("pub struct CustomData"));
        assert!(code.contains("pub enum LocationEnum"));
        assert!(!code.contains("use super::common"));
    }

    #[test]
    fn generic_affected_message_gates_its_action_impl_by_cfg_too_not_just_the_struct() {
        // A field with no spec-given bound makes the message generic (see
        // `own_params`). Both the alloc and non-alloc bodies -- struct AND
        // its `impl Action` -- must each carry their own `#[cfg]` gate;
        // otherwise one mode's `impl Action for Foo` (accidentally
        // ungated) and the other mode's `impl<const N: usize> Action for
        // Foo<N>` both compile unconditionally and collide via the
        // default-applied `Foo<N>`.
        let mut schema = sample_schema();
        schema.message.fields[0].ty = RustType::UnboundedString(ConstParam {
            name: "AUTHORIZE_REQUEST_ID_TAG_CAP".to_string(),
            default: 1024,
        });

        let code = generate(schema);

        // One struct + one impl per mode = each cfg gate appears twice.
        let count = |needle: &str| code.matches(needle).count();
        let alloc_gates = count("cfg (feature = \"alloc\")") + count("cfg(feature = \"alloc\")");
        let no_alloc_gates =
            count("cfg (not (feature = \"alloc\"))") + count("cfg(not(feature = \"alloc\"))");

        assert_eq!(alloc_gates, 2, "expected the struct AND the impl to be #[cfg(feature = \"alloc\")]-gated");
        assert_eq!(no_alloc_gates, 2, "expected the struct AND the impl to be #[cfg(not(feature = \"alloc\"))]-gated");
    }

    #[test]
    fn nested_struct_does_not_implement_action() {
        let mut schema = sample_schema();
        schema.types.push(GeneratedType::Struct(RustStruct {
            name: "ChargingStation".to_string(),
            action: None,
            description: None,
            fields: vec![RustField {
                name: "model".to_string(),
                ty: RustType::BoundedString(20),
                optional: false,
                description: None,
            }],
        }));

        let code = generate(schema);

        assert!(code.contains("pub struct ChargingStation"));
        assert!(!code.contains("impl crate::Action for ChargingStation"));
    }

    #[test]
    fn local_type_is_referenced_without_crate_prefix() {
        let mut schema = sample_schema();
        schema.message.fields[0].ty = RustType::Local("ChargingStation".to_string());

        let code = generate(schema);

        assert!(code.contains("pub id_tag: ChargingStation"));
    }

    #[test]
    fn enum_variant_with_invalid_ident_gets_serde_rename() {
        let mut schema = sample_schema();
        schema.types.push(GeneratedType::Enum(RustEnum {
            name: "MeasurandEnum".to_string(),
            description: None,
            variants: vec![RustVariant {
                ident: "VoltageMaximum".to_string(),
                raw: "Voltage.Maximum".to_string(),
            }],
        }));

        let code = generate(schema);

        assert!(code.contains("pub enum MeasurandEnum"));
        assert!(code.contains("VoltageMaximum"));
        assert!(code.contains("rename = \"Voltage.Maximum\""));
    }

    #[test]
    fn bounded_vec_renders_as_heapless_vec_with_capacity() {
        let mut schema = sample_schema();
        schema.message.fields[0].ty =
            RustType::Vec(Box::new(RustType::BoundedString(10)), 5);

        let code = generate(schema);

        assert!(code.contains("heapless :: Vec < heapless :: String < 10usize > , 5usize >")
            || code.contains("heapless::Vec<heapless::String<10usize>, 5usize>"));
    }

    #[test]
    fn vec_of_floats_disables_eq_derive() {
        let mut schema = sample_schema();
        schema.message.fields[0].ty = RustType::Vec(Box::new(RustType::Number), 5);

        let code = generate(schema);

        assert!(code.contains("PartialEq"));
        assert!(!code.contains("PartialEq, Eq"));
    }

    #[test]
    fn oversized_bounded_vec_renders_as_alloc_vec_under_alloc_mode() {
        let ty = RustType::Vec(Box::new(RustType::BoundedString(10)), 1024);

        let tokens = rust_type(&ty, true, &HashMap::new());

        let inner = quote! { heapless::String<10usize> };
        let expected = quote! { alloc::vec::Vec<#inner> };
        assert_eq!(tokens.to_string(), expected.to_string());
    }

    #[test]
    fn oversized_bounded_vec_stays_heapless_without_alloc_mode() {
        let ty = RustType::Vec(Box::new(RustType::BoundedString(10)), 1024);

        let tokens = rust_type(&ty, false, &HashMap::new());

        assert_eq!(
            tokens.to_string(),
            quote! { heapless::Vec<heapless::String<10usize>, 1024usize> }.to_string()
        );
    }

    #[test]
    fn small_bounded_vec_stays_heapless_even_under_alloc_mode() {
        let ty = RustType::Vec(Box::new(RustType::BoundedString(10)), 5);

        let tokens = rust_type(&ty, true, &HashMap::new());

        assert_eq!(
            tokens.to_string(),
            quote! { heapless::Vec<heapless::String<10usize>, 5usize> }.to_string()
        );
    }

    #[test]
    fn a_lone_oversized_bounded_vec_still_splits_into_alloc_and_no_alloc_variants() {
        // No `UnboundedString`/`UnboundedVec` field anywhere -- normally
        // that means a single struct definition. An oversized *bounded*
        // `Vec` must force the alloc/no_alloc split too, or the alloc build
        // never gets a chance to switch it to `alloc::Vec`.
        let mut schema = sample_schema();
        schema.message.fields[0].ty =
            RustType::Vec(Box::new(RustType::BoundedString(10)), 1024);

        let code = generate(schema);

        assert!(code.contains("cfg (feature = \"alloc\")") || code.contains("cfg(feature = \"alloc\")"));
        assert!(code.contains("alloc :: vec :: Vec") || code.contains("alloc::vec::Vec"));
        assert!(code.contains("heapless :: Vec") || code.contains("heapless::Vec"));
    }
}
